// Desktop OS – Deel II: Windows – Werkcollege 1
// v = vraag, a = antwoord, o = onderwerp, uitleg = extra uitleg, img/imgAntwoord = afbeelding (map afbeeldingen/)
// wit: true = witte kaart die de cursus voorstelt · extra: true = extra info, niet uit de cursus (turquoise rand)
// oefening: true = blauwe oefenkaart: typ het commando. In a staan commando's na "$ "; regels die met 2 spaties beginnen zijn toetsen of uitvoer.
// De structuur onderaan bepaalt het overzicht rechts.

const kaarten_DOS_windows_wc1 = [
  // ===== Microsoft CEO's =====
  { v: "Wie staan er op de foto in de cursus? Geef links, midden en rechts.", a: "Links Satya Nadella, in het midden Bill Gates, rechts Steve Ballmer.", o: "Microsoft CEO's", img: "afbeeldingen/DesktopOS_windows_wc1/ceo.jpg",
    uitleg: "Het zijn de drie CEO's die Microsoft tot nu toe had.\n\nIn de cursus vul je hun namen in onder de foto.\n\nAchtergrond (wordt niet gevraagd): Bill Gates richtte Microsoft in 1975 op met Paul Allen en was CEO tot 2000. Steve Ballmer was CEO van 2000 tot 2014. Satya Nadella is CEO sinds 2014." },
  { v: "Welke drie mensen waren (of zijn) CEO van Microsoft?", a: "Bill Gates, Steve Ballmer en Satya Nadella.", o: "Microsoft CEO's",
    uitleg: "In volgorde: Bill Gates, daarna Steve Ballmer, nu Satya Nadella." },
  // ===== RDP =====
  { v: "Met wat voor account maak je verbinding met de Windows-instantie?", a: "Met een account waarop je adminrechten hebt, net zoals bij Linux.", o: "RDP",
    uitleg: "Adminrechten = je mag alles op die pc: programma's installeren, instellingen van Windows wijzigen, gebruikers aanmaken. Dat heb je nodig voor de opdrachten van de werkcolleges." },
  { v: "Welke VM's staan klaar voor de Windows-werkcolleges, en wie zet ze aan en uit?", a: "Virtuele Windows 11-machines. Je zet ze zelf aan en uit, net zoals je Linux-machines.", o: "RDP",
    uitleg: "VM = virtuele machine: een computer die als programma op een server draait. Je beheert ze in Azure (portal.azure.com); daar zie je ook het IP-adres en de DNS-naam van je VM." },
  { v: "Wat is SSH echt?", a: "SSH (Secure Shell) is een manier om veilig met een andere computer te praten over een onveilig netwerk, meestal het internet. Je logt in op een server en voert daar commando's uit alsof je er zelf achter zit.", o: "RDP", extra: true,
    uitleg: "Bij Linux verbond je zo met je VM. Bij Windows gebruik je RDP: dan zie je het hele bureaublad in plaats van enkel tekst." },
  { v: "Wat gebeurt er bij ssh gebruiker@server.be?", a: "1. Verbinding: je computer (de client) maakt een TCP-verbinding met de server, standaard op poort 22.\n2. Afspraken: client en server kiezen samen de versleutelingsalgoritmes.\n3. Sleuteluitwisseling: met Diffie-Hellman maken ze samen een geheime sleutel, zonder dat die ooit over het netwerk gaat.\n4. De server bewijst wie hij is met zijn host key.\n5. Jij bewijst wie je bent: met een wachtwoord, of beter met een sleutelpaar.\n6. Vanaf nu is alles wat je typt en terugkrijgt versleuteld.", o: "RDP", extra: true,
    uitleg: "Host key: de eerste keer vraagt SSH of je hem vertrouwt (\"Are you sure you want to continue connecting?\"). Daarna onthoudt je computer hem in ~/.ssh/known_hosts. Verandert hij plots, dan krijg je een luide waarschuwing: dat kan wijzen op een man-in-the-middle-aanval.\n\nVergelijking: een telefoongesprek waarin jullie samen een geheime taal verzinnen terwijl iedereen meeluistert, en toch begrijpt niemand anders die taal. Daarna toont de server zijn paspoort, en jij bewijst met een zegel dat alleen jij bezit wie je bent." },
  { v: "SSH-sleutelparen", a: "Met ssh-keygen maak je twee bestanden: een privésleutel (bv. id_ed25519) die je nooit deelt, en een publieke sleutel (id_ed25519.pub) die je op de server zet in ~/.ssh/authorized_keys.", o: "RDP", extra: true,
    uitleg: "Bij het inloggen stuurt de server een soort uitdaging. Je computer ondertekent die met de privésleutel, en de server controleert de handtekening met de publieke sleutel. Zo bewijs je dat je de privésleutel hebt, zonder hem ooit te versturen: veiliger en handiger dan een wachtwoord." },
  { v: "SSH: meer dan alleen inloggen", a: "SSH is een algemene versleutelde tunnel. Je kan er ook mee: bestanden kopiëren (scp, sftp), Git gebruiken met GitHub (git@github.com:… is gewoon SSH), port forwarding (ssh -L 8080:localhost:80 server) en commando's op afstand uitvoeren (ssh server \"df -h\").", o: "RDP", extra: true,
    uitleg: "Port forwarding: een dienst op de server bereiken alsof hij lokaal op je eigen computer draait." },
  { v: "Gebruik je SSH om met de Windows-VM te verbinden? Wat dan wel?", a: "Neen, je gebruikt RDP.", o: "RDP" },
  { v: "Waarvoor staat RDP?", a: "Remote Desktop Protocol.", o: "RDP" },
  { v: "Wat kan je met RDP, meer dan met een SSH-verbinding?", a: "Niet alleen vanop afstand verbinding maken met een pc, maar de pc ook overnemen.", o: "RDP",
    uitleg: "Je ziet het volledige bureaublad.\n\nBij Linux was het een SSH-verbinding (enkel tekst). Met RDP zie je het volledige bureaublad.\n\nJe ziet het scherm van de andere pc en je bedient hem met je eigen muis en toetsenbord." },
  { v: "Wie ontwikkelde en patenteerde RDP?", a: "Microsoft zelf.", o: "RDP" },
  { v: "Waarvoor gebruik je RDP in het bedrijfsleven?", a: "Om gemakkelijk hulp op afstand te bieden.", o: "RDP" },
  { v: "Waar vind je het IP-adres en de DNS-naam van je Windows-VM?", a: "In Azure: portal.azure.com.", o: "RDP", img: "afbeeldingen/DesktopOS_windows_wc1/azure.jpg" },
  { v: "Welk programma gebruik je om met de VM te verbinden? Moet je het installeren?", a: "Remote Desktop (Connection). Neen, het staat standaard geïnstalleerd bij Windows.", o: "RDP" },
  { v: "Wat vul je in op de plaats van het vakje?", a: "De DNS-naam van je VM, met de poort erachter: DNS-naam:poort.", o: "RDP", img: "afbeeldingen/DesktopOS_windows_wc1/rdp_verbinden_vraag.jpg", imgAntwoord: "afbeeldingen/DesktopOS_windows_wc1/rdp_verbinden.jpg",
    uitleg: "De cursus zegt IP, maar in de praktijk werkt enkel DNS-naam:poort. De DNS-naam vind je via portal.azure.com; het IP op de afbeelding is maar een voorbeeld.\n\nDe cursus zegt dat je je IP invult, maar in de praktijk werkt IP:poort niet en DNS-naam:poort wel. De DNS-naam van je VM vind je via portal.azure.com. Het IP-adres op de afbeelding is maar een voorbeeld. Je credentials worden gevraagd als je op Connect klikt." },
  { v: "Hoe zie je de extra opties (tabbladen) in Remote Desktop Connection?", a: "Via Show Options.", o: "RDP" },
  { v: "Wat stel je in onder Local Resources?", a: "Welke resources je doorgeeft aan of gebruikt van de remote desktop.", o: "RDP",
    uitleg: "Bv. audio, printers, klembord, smart cards, poorten, schijven.\n\nBv. de helpdesk neemt je pc over om een probleem op te lossen." },
  { v: "Op welke waarde zet je Apply Windows key combinations, en waarom?", a: "On the remote computer: zo voert de remote computer de toetscombinaties uit (nodig om de sneltoetsen te testen).", o: "RDP", img: "afbeeldingen/DesktopOS_windows_wc1/rdp_local_resources_vraag.jpg", imgAntwoord: "afbeeldingen/DesktopOS_windows_wc1/rdp_local_resources.jpg",
    uitleg: "Nodig, want in het volgende deel test je de sneltoetsen uit op de VM. Anders voert je eigen pc bv. Alt+Tab uit." },
  // ===== Sneltoetsen =====
  { v: "Wat doet Alt+F4 als je op het bureaublad staat?", a: "Het menu om Windows af te sluiten.", o: "Sneltoetsen",
    uitleg: "Staat er een venster vooraan, dan sluit Alt+F4 dat venster of programma. Is er geen venster actief (je staat op het bureaublad), dan opent het venster Shut Down Windows: daar kies je afsluiten, herstarten, afmelden ..." },
  { v: "Waarom gebruik je via RDP Ctrl+Alt+End in plaats van Ctrl+Alt+Delete?", a: "Anders vangt je eigen pc Ctrl+Alt+Delete op.", o: "Sneltoetsen",
    uitleg: "Ctrl+Alt+Delete wordt altijd opgevangen door de pc waaraan je zelf zit, ook als Apply Windows key combinations op On the remote computer staat. Met Ctrl+Alt+End krijg je het beveiligingsscherm van de VM: Lock, Sign out, Change a password, Task Manager." },
  { v: "Welke 4 keuzes geeft het projectiemenu (Win+P)?", a: "Alleen pc-scherm, dupliceren, uitbreiden en alleen tweede scherm.", o: "Sneltoetsen",
    uitleg: "1. Alleen pc-scherm (PC screen only): enkel je eigen scherm.\n2. Dupliceren (Duplicate): op beide schermen hetzelfde beeld.\n3. Uitbreiden (Extend): het tweede scherm is extra ruimte naast je eigen scherm.\n4. Alleen tweede scherm (Second screen only): enkel de projector of het tweede scherm." },
  { v: "Wat doet Ctrl+A?", a: "Alles selecteren.", o: "Sneltoetsen" },
  { v: "Wat doet Ctrl+X?", a: "Knippen.", o: "Sneltoetsen",
    uitleg: "De selectie verdwijnt en komt op het klembord." },
  { v: "Kopieer de selectie, op 2 manieren.", a: "  Ctrl+C\n  Ctrl+Insert", o: "Sneltoetsen", oefening: true },
  { v: "Plak vanaf het klembord, op 2 manieren.", a: "  Ctrl+V\n  Shift+Insert", o: "Sneltoetsen", oefening: true },
  { v: "Wat doet Ctrl+Z, en wat doet Ctrl+Y?", a: "Ctrl+Z = ongedaan maken. Ctrl+Y = opnieuw uitvoeren.", o: "Sneltoetsen" },
  { v: "Wissel tussen de geopende vensters.", a: "  Alt+Tab", o: "Sneltoetsen", oefening: true,
    uitleg: "Alt ingedrukt houden en Tab herhalen." },
  { v: "Sluit het actieve venster.", a: "  Alt+F4", o: "Sneltoetsen", oefening: true },
  { v: "Open rechtstreeks Taakbeheer.", a: "  Ctrl+Shift+Escape", o: "Sneltoetsen", oefening: true },
  { v: "Open het beveiligingsscherm, gewoon en via RDP.", a: "  Ctrl+Alt+Delete\n  Ctrl+Alt+End (via RDP)", o: "Sneltoetsen", oefening: true },
  { v: "Vergrendel je pc.", a: "  Win+L", o: "Sneltoetsen", oefening: true },
  { v: "Wat doet F5, en wat doet F11?", a: "F5 = vernieuwen. F11 = volledig scherm.", o: "Sneltoetsen",
    uitleg: "F5 vernieuwt bv. een webpagina of een map in de Verkenner. F11 zet volledig scherm aan; nog eens F11 zet het weer uit." },
  { v: "Zet een venster op de linker- of rechterhelft van het scherm.", a: "  Win+pijl-links\n  Win+pijl-rechts", o: "Sneltoetsen", oefening: true },
  { v: "Verwijder een bestand zonder het in de prullenbak te zetten.", a: "  Shift+Delete", o: "Sneltoetsen", oefening: true },
  { v: "Open het projectiemenu (tweede scherm of projector).", a: "  Win+P", o: "Sneltoetsen", oefening: true },
  { v: "Verplaats het actieve venster naar een ander scherm.", a: "  Win+Shift+pijl-links\n  Win+Shift+pijl-rechts", o: "Sneltoetsen", oefening: true },
  { v: "Wat doet Win + de pijltjestoetsen? En welke tool geeft meer opties?", a: "Vensters schikken (helft links/rechts, maximaliseren, verkleinen). Meer opties: Fancy Zones.", o: "Sneltoetsen" },
  { v: "Start een programma als administrator met het toetsenbord.", a: "  (typ de naam in het startmenu)\n  Ctrl+Shift+Enter", o: "Sneltoetsen", oefening: true,
    uitleg: "Je kan de naam ook in het venster Run (Win+R) typen en dan Ctrl+Shift+Enter drukken." },
  { v: "Open het venster Uitvoeren (Run).", a: "  Win+R", o: "Sneltoetsen", oefening: true,
    uitleg: "Bv. typ cmd en druk Enter om de Command Prompt te starten." },
  { v: "Toon het bureaublad.", a: "  Win+D", o: "Sneltoetsen", oefening: true,
    uitleg: "Nog eens Win+D = alles terug." },
  // ===== Windows Terminal =====
  { v: "CMD of PowerShell: tekst of objecten", a: "CMD geeft gewone tekst terug. PowerShell geeft objecten terug: elk resultaat heeft eigenschappen die je kan opvragen en filteren.", o: "Windows Terminal", extra: true,
    uitleg: "Voorbeeld: in CMD toont dir een lijst tekst. In PowerShell geeft Get-ChildItem | Where-Object Length -gt 1MB meteen enkel de bestanden groter dan 1 MB, omdat elk bestand een object is met een eigenschap Length." },
  { v: "CMD of PowerShell: namen van commando's", a: "CMD heeft korte, oude commando's: dir, cd, copy, del. PowerShell gebruikt de vorm Werkwoord-Zelfstandignaamwoord: Get-ChildItem, Copy-Item, Remove-Item.", o: "Windows Terminal", extra: true,
    uitleg: "Voor de bekende namen zijn er aliassen: dir, ls, cd, cp en rm werken in PowerShell als afkorting." },
  { v: "CMD of PowerShell: opties", a: "In CMD schrijf je opties met een slash: dir /s. In PowerShell met een minteken: Get-ChildItem -Recurse.", o: "Windows Terminal", extra: true },
  { v: "CMD of PowerShell: wat werkt anders?", a: "< (input redirection) werkt niet in PowerShell. && en || werken pas in PowerShell 7, niet in de ingebouwde Windows PowerShell 5.1.", o: "Windows Terminal", extra: true,
    uitleg: "Daarom gebruik je voor de opdrachten met <, && en || (sorteren, ip.txt, TryMulti) het best CMD, zoals de cursus doet." },
  { v: "CMD of PowerShell: scripts", a: "CMD-scripts zijn .bat- of .cmd-bestanden en zijn beperkt. PowerShell-scripts zijn .ps1-bestanden: een echte programmeertaal.", o: "Windows Terminal", extra: true },
  { v: "CMD of PowerShell: waarvoor?", a: "CMD is eenvoudig en oud, vooral voor bestanden en eenvoudige taken. PowerShell beheert heel Windows (services, register, gebruikers, Azure …) en is wat systeembeheerders vandaag vooral gebruiken.", o: "Windows Terminal", extra: true,
    uitleg: "Voor dit werkcollege volstaat CMD." },
  { v: "Terminal, shell en ssh: drie verschillende dingen", a: "Windows Terminal is het venster (een terminal-emulator): het toont tekst en geeft je toetsaanslagen door, maar voert zelf niets uit. PowerShell (of CMD) is de shell: die begrijpt je commando's en voert ze uit. ssh is gewoon een programma dat een verbinding opent.", o: "Windows Terminal", extra: true,
    uitleg: "In Windows Terminal open je verschillende shells: PowerShell, Command Prompt, Linux via WSL of een SSH-sessie.\nDe OpenSSH-client zit sinds Windows 10 (versie 1809) standaard in Windows: C:\\Windows\\System32\\OpenSSH\\ssh.exe. Je start hem vanuit elke shell." },
  { v: "Windows PowerShell 5.1 en PowerShell 7+", a: "Windows PowerShell 5.1 zit standaard ingebouwd in Windows (het blauwe venster). PowerShell 7+ is de nieuwere, cross-platform versie die je apart installeert.", o: "Windows Terminal", extra: true,
    uitleg: "PowerShell werkt met objecten in plaats van gewone tekst, wat het anders maakt dan bash op Linux." },
  { v: "Hoe hangen Terminal, PowerShell en ssh samen?", a: "Windows Terminal (het venster) → PowerShell (de shell waarin je typt) → ssh gebruiker@server (opent de verbinding) → bash op de server (vanaf nu typ je op de andere computer). Met exit ben je terug in je lokale PowerShell.", o: "Windows Terminal", extra: true,
    uitleg: "Praktisch: een sleutel maken doe je met ssh-keygen in PowerShell; de sleutels komen in C:\\Users\\<jouwnaam>\\.ssh\\. Verbinden: ssh gebruiker@server.be. Handig: in Windows Terminal kan je een eigen profiel maken dat meteen ssh gebruiker@server.be start, zodat je met één klik op je server zit." },
  { v: "Wat is Windows Terminal?", a: "Een applicatie voor CLI-gebruikers, standaard geïnstalleerd op Windows 11.", o: "Windows Terminal", img: "afbeeldingen/DesktopOS_windows_wc1/terminal_store.jpg" },
  { v: "Hoe installeer je Windows Terminal als het niet geïnstalleerd is?", a: "Via de Windows Store.", o: "Windows Terminal" },
  { v: "Waarom werd Windows Terminal ontwikkeld?", a: "Als antwoord op veelgevraagde features door de community.", o: "Windows Terminal" },
  { v: "Geef een handige feature van Windows Terminal.", a: "Tegelijk verschillende tabbladen open hebben, elk met een sessie naar een shell (bv. CMD, PowerShell, een SSH-verbinding).", o: "Windows Terminal",
    uitleg: "Handig als je veel uitvoer wil zien, bv. bij tree of dir /s." },
  { v: "Hoe open je een nieuw tabblad in Terminal? En met een ander profiel?", a: "Met de + (default profile). Een ander profiel kies je via het drop-downmenu.", o: "Windows Terminal" },
  { v: "Hoe start je een Command Prompt-sessie via Terminal?", a: "Via het drop-downmenu naast de + kies je Command Prompt.", o: "Windows Terminal", img: "afbeeldingen/DesktopOS_windows_wc1/terminal_menu.jpg" },
  { v: "Wat is PowerShell?", a: "De nieuwere commandline tool van Microsoft, vergelijkbaar met de shell van Linux/Unix, maar met Windows-commando's.", o: "Windows Terminal" },
  { v: "Waarom werken Linux-commando's zoals ls ook in PowerShell?", a: "Er zijn aliassen gemaakt voor Linux-commando's.", o: "Windows Terminal" },
  { v: "Met welke shell werken we in de werkcolleges? Werken de commando's ook in PowerShell?", a: "Met de \"oude\" DOS Command Prompt (CMD). Ja, ze werken ook in PowerShell.", o: "Windows Terminal",
    uitleg: "In het menu zie je o.a. Windows PowerShell, Command Prompt en Azure Cloud Shell." },
  { v: "Wanneer is de shell vooral handig?", a: "Om gegevens op te vragen die niet zo gemakkelijk (of niet) via de grafische omgeving beschikbaar zijn.", o: "Windows Terminal" },
  { v: "Waarom gebruiken veel informatici nog de CLI?", a: "Krachtige omgeving: veel informatie opvragen, operaties uitvoeren en taken automatiseren.", o: "Windows Terminal" },
  { v: "Ga fullscreen in Terminal.", a: "  F11", o: "Windows Terminal", oefening: true,
    uitleg: "Nog eens F11 = terug naar een gewoon venster." },
  { v: "Kopieer een commando uit Terminal en plak het opnieuw in Terminal.", a: "  selecteer de tekst met de muis\n  Ctrl+C\n  rechtermuisklik", o: "Windows Terminal", oefening: true,
    uitleg: "Kopiëren met Ctrl+C na het selecteren, plakken met een rechtermuisklik.\n\nOpgelet: in Terminal plak je met een rechtermuisklik, niet met een menu zoals in andere programma's. Zo neem je snel een commando over uit de cursus of uit een andere tab." },
  { v: "Hoe kopieer en plak je in Terminal?", a: "Kopiëren: selecteren met de muis + Ctrl+C. Plakken: rechtermuisklik.", o: "Windows Terminal" },
  { v: "Wat doet Tab in CMD? En als je opnieuw Tab drukt?", a: "Autocompletion. Opnieuw Tab = door de andere mogelijkheden gaan.", o: "Windows Terminal",
    uitleg: "Tab vult het begin van een commando, een map of een bestand aan." },
  { v: "Waar verander je het standaardprofiel van Terminal?", a: "In de settings van Terminal.", o: "Windows Terminal" },
  { v: "Wat kan je veranderen via de settings van Terminal?", a: "Het standaardprofiel en de grafische instellingen.", o: "Windows Terminal",
    uitleg: "Standaardprofiel = de shell die opstart als je Terminal opent, bv. Command Prompt in plaats van PowerShell. Grafische instellingen = bv. kleuren, lettertype en achtergrond." },
  { v: "Wat is Command Prompt (cmd.exe), en waarvan is het afgeleid?", a: "De oude opdrachtregel van Windows, afgeleid van MS-DOS.", o: "Windows Terminal",
    uitleg: "MS-DOS was het besturingssysteem van Microsoft voor Windows bestond: je werkte er enkel met getypte commando's. Command Prompt neemt die manier van werken over binnen Windows." },
  { v: "Geef 4 simpele commando's van Command Prompt.", a: "dir, cd, copy en ipconfig.", o: "Windows Terminal",
    uitleg: "dir = de inhoud van een map tonen.\ncd = naar een andere map gaan.\ncopy = een bestand kopiëren.\nipconfig = je netwerkinstellingen tonen." },
  { v: "Waarmee werkt Command Prompt (tekst of objecten), en in welke bestanden script je ermee?", a: "Alleen met tekst. Beperkt scripten in .bat-bestanden.", o: "Windows Terminal",
    uitleg: "Alleen tekst: wat een commando teruggeeft, is gewoon tekst op het scherm. Een .bat-bestand is een tekstbestand met cmd-commando's onder elkaar, die na elkaar worden uitgevoerd." },
  { v: "Wordt Command Prompt nog verder ontwikkeld?", a: "Neen. Het wordt nog ondersteund, maar Microsoft ontwikkelt het niet meer verder.", o: "Windows Terminal",
    uitleg: "Ondersteund = het zit nog in Windows en werkt. Er komen alleen geen nieuwe mogelijkheden meer bij: Microsoft steekt die in PowerShell." },
  { v: "Wat is PowerShell, ten opzichte van Command Prompt?", a: "De modernere en krachtigere opvolger van Command Prompt.", o: "Windows Terminal" },
  { v: "PowerShell werkt met objecten in plaats van alleen tekst. Wat is daar het voordeel van? Geef het voorbeeld.", a: "Je kan resultaten makkelijk filteren, sorteren en doorgeven.\nGet-Process | Sort-Object CPU", o: "Windows Terminal",
    uitleg: "Get-Process = geef de programma's die nu draaien. Elk programma is een object met eigenschappen, zoals de naam en CPU (hoeveel rekentijd het gebruikt).\n| = geef het resultaat door aan het volgende commando.\nSort-Object CPU = sorteer op de eigenschap CPU.\nIn Command Prompt krijg je enkel tekst terug, en dan moet je zelf zoeken waar in de tekst de waarde staat." },
  { v: "Hoe heten commando's in PowerShell, en welke vorm hebben ze? Geef 2 voorbeelden.", a: "Cmdlets, met de vorm werkwoord-zelfstandig naamwoord: Get-ChildItem en Set-Location.", o: "Windows Terminal",
    uitleg: "Get-ChildItem = geef de inhoud van een map (zoals dir in cmd).\nSet-Location = stel de map in waar je staat (zoals cd in cmd).\nHet werkwoord zegt wat je doet (Get = opvragen, Set = instellen), het zelfstandig naamwoord waarop." },
  { v: "Waarvoor is PowerShell gebouwd, en in welke bestanden script je ermee?", a: "Voor beheer en automatisering van Windows, servers, Azure enzovoort, met scripts in .ps1-bestanden.", o: "Windows Terminal",
    uitleg: "Automatisering = taken die je anders met de hand doet, laten uitvoeren door een script. Azure is het cloudplatform van Microsoft." },
  { v: "Waarom werken de meeste oude cmd-commando's ook in PowerShell?", a: "Dankzij aliassen.", o: "Windows Terminal",
    uitleg: "Een alias is een tweede naam voor een cmdlet. Typ je dir in PowerShell, dan voert het eigenlijk Get-ChildItem uit. cd is een alias voor Set-Location." },
  { v: "Op welke systemen draait PowerShell 7?", a: "Op Windows, Linux en macOS.", o: "Windows Terminal" },
  { v: "Is SSH een shell zoals Command Prompt en PowerShell? Wat is het dan wel?", a: "Neen. Het is een protocol om veilig verbinding te maken met een andere computer via het netwerk.", o: "Windows Terminal",
    uitleg: "Een shell begrijpt je commando's en voert ze uit. Een protocol is een afspraak over hoe twee computers met elkaar communiceren. SSH zorgt alleen voor de verbinding; op de andere computer draait een eigen shell die je commando's uitvoert." },
  { v: "Hoe maak je vanuit PowerShell of cmd een SSH-verbinding als gebruiker met de computer 192.168.1.10?", a: "ssh gebruiker@192.168.1.10", o: "Windows Terminal",
    uitleg: "ssh = start de SSH-client.\ngebruiker = de gebruikersnaam op de andere computer.\n@192.168.1.10 = het IP-adres van de andere computer." },
  { v: "Waar worden je commando's uitgevoerd na een SSH-verbinding, en wat gebeurt er met wat je verstuurt?", a: "Op die andere computer, vaak een Linux-server of een Raspberry Pi. Alles wat je verstuurt is versleuteld.", o: "Windows Terminal",
    uitleg: "Versleuteld = wie het netwerkverkeer onderschept, kan het niet lezen, ook je wachtwoord niet." },
  // ===== Bestandsbeheer =====
  { v: "Slash / en backslash \\ in CMD", a: "In dir /o:d is de / een schakelaar (switch). Hij zegt tegen het commando: \"nu volgt een optie\". /o betekent order (sorteren), :d betekent op datum. /o:-d keert dat om, dus nieuwste eerst.\nDe \\ gebruikt Windows om mappen in een pad te scheiden, zoals in C:\\Users\\Jan\\Documents. Het zijn dus twee verschillende tekens met twee verschillende taken.", o: "Bestandsbeheer", extra: true },
  { v: "Hoe bekijk je de mogelijkheden (help) van een commando? Geef het voorbeeld met dir.", a: "C:\\> commando /?\nC:\\> dir /?", o: "Bestandsbeheer", oefening: true,
    uitleg: "/? achter een commando toont de help: alle opties van dat commando.\ndir /? = de help van dir.\n\nBv. team.txt of term.txt." },
  { v: "Toon de inhoud van de map waar je nu staat.", a: "C:\\> dir", o: "Bestandsbeheer", oefening: true,
    uitleg: "dir = toon de inhoud van een map: de bestanden en submappen, met hun grootte en datum.\nZonder iets erachter toont dir de map waar je nu staat, dus de map die in je prompt staat (hier C:\\)." },
  { v: "Toon de eigenschappen van het bestand resultaat.txt.", a: "C:\\> dir resultaat.txt", o: "Bestandsbeheer", oefening: true,
    uitleg: "dir met een bestandsnaam erachter toont enkel dat ene bestand, met zijn datum, uur en grootte." },
  { v: "Wat doet het commando dir?", a: "De inhoud van een map tonen, of de eigenschappen van een bestand als je de bestandsnaam meegeeft.", o: "Bestandsbeheer" },
  { v: "Welke optie van dir zoekt recursief?", a: "/s", o: "Bestandsbeheer" },
  { v: "Wat doet dir /s prese*.ppt?", a: "In de huidige map en alle submappen de bestanden tonen die beginnen met prese en de extensie .ppt hebben.", o: "Bestandsbeheer" },
  { v: "Waarvoor staan * en ? als jokerteken?", a: "* = 0 tot meerdere tekens. ? = 1 teken.", o: "Bestandsbeheer" },
  { v: "Wat toont dir t??m.txt?", a: "Mappen en bestanden: eerste letter t, dan 2 willekeurige letters, dan als laatste letter m, extensie txt.", o: "Bestandsbeheer" },
  { v: "Hoe toon je de bestanden in C:\\Windows geordend op datum? En in omgekeerde volgorde?", a: "C:\\Windows> dir /o:d\nC:\\Windows> dir /o:-d", o: "Bestandsbeheer", oefening: true,
    uitleg: "dir = toon de inhoud van de map.\n/o:d = order (sorteer) op date: oudste eerst. Ook: dir /od.\n/o:-d = het minteken keert de volgorde om: nieuwste eerst." },
  { v: "Waarom zijn jokertekens gevaarlijk?", a: "In combinatie met del of erase verwijder je in één keer veel bestanden.", o: "Bestandsbeheer" },
  { v: "Ga naar de map C:\\Windows en bekijk de help van dir.", a: "C:\\> cd c:\\Windows\nC:\\Windows> dir /?", o: "Bestandsbeheer", oefening: true,
    uitleg: "cd c:\\Windows = ga naar de map Windows op C: (de prompt wordt C:\\Windows>).\ndir /? = toon de help van dir." },
  { v: "Zoek in de huidige map en alle submappen de bestanden die met prese beginnen en de extensie .ppt hebben.", a: "C:\\> dir /s prese*.ppt", o: "Bestandsbeheer", oefening: true,
    uitleg: "dir = toon bestanden.\n/s = zoek ook in alle submappen (recursief).\nprese*.ppt = * staat voor 0 tot meerdere tekens: alles wat met prese begint en op .ppt eindigt." },
  { v: "Toon de bestanden van 4 letters die met t beginnen en op m eindigen, met de extensie .txt.", a: "C:\\> dir t??m.txt", o: "Bestandsbeheer", oefening: true,
    uitleg: "dir = toon bestanden.\nt??m.txt = ? staat voor precies 1 teken: een t, 2 willekeurige letters, een m, en de extensie .txt." },
  // ===== Navigeren =====
  { v: "Wat betekent cd \\?", a: "cd \\ is een commando in de Windows-opdrachtprompt (CMD) en betekent: ga naar de hoofdmap (root) van de huidige schijf. cd = change directory, oftewel \"wissel van map\". \\ = de hoofdmap van de schijf.", o: "Navigeren", extra: true,
    uitleg: "Voorbeeld:\nC:\\Users\\Jan\\Documenten\\Projecten> cd \\\nC:\\>" },
  { v: "cd \\: hoe diep je ook zit", a: "Hoe diep je ook in de mappenstructuur zit, je springt meteen terug naar C:\\, of naar de root van de schijf waarop je op dat moment werkt, zoals D:\\.", o: "Navigeren", extra: true },
  { v: "Verwante commando's van cd", a: "cd .. gaat één map omhoog. cd zonder iets erachter toont de huidige map.", o: "Navigeren", extra: true },
  { v: "cd / op Linux en macOS", a: "Op Linux en macOS werkt dit anders. Daar gebruik je / in plaats van \\, dus cd / brengt je naar de root.", o: "Navigeren", extra: true },
  { v: "Hoe ga je naar de D-schijf?", a: "C:\\> D:", o: "Navigeren", oefening: true,
    uitleg: "De volumeletter met een dubbelpunt = ga naar dat volume. Werkt enkel als die schijf bestaat.\n\nAchtergrond (wordt niet gevraagd): in CMD schrijf je paden met een backslash \\ en opties met een slash / (dir /s). In Linux is het net andersom." },
  { v: "Hoe ga je naar de submap mijndir?", a: "C:\\> cd mijndir", o: "Navigeren", oefening: true,
    uitleg: "cd = change directory: ga naar een andere map.\nmijndir = een submap van de map waar je nu staat." },
  { v: "Hoe ga je naar de hoger gelegen map?", a: "C:\\mijndir> cd ..", o: "Navigeren", oefening: true,
    uitleg: "cd = change directory.\n.. = de map erboven (de bovenliggende map)." },
  { v: "Hoe ga je naar de submap test van volume C:\\?", a: "C:\\> cd c:\\test", o: "Navigeren", oefening: true,
    uitleg: "cd = change directory.\nc:\\test = het volledige pad: de map test op C:." },
  { v: "Hoe ga je naar de root van het huidige volume?", a: "C:\\test> cd \\", o: "Navigeren", oefening: true,
    uitleg: "cd = change directory.\n\\ = de root (de bovenste map) van het volume. Je springt er meteen naartoe, hoe diep je ook zit.\n\nBv. van c:\\Documents and Settings\\jos naar c:\\." },
  { v: "Welk commando maakt een nieuwe map aan?", a: "mkdir", o: "Navigeren" },
  { v: "Ga naar je C-schijf en maak een map test.", a: "C:\\> c:\nC:\\> cd \\\nC:\\> mkdir test", o: "Navigeren", oefening: true,
    uitleg: "c: = ga naar het volume C.\ncd \\ = ga naar de root van C:.\nmkdir test = maak een nieuwe map test.\n\nOpdracht: c: · cd \\ · mkdir test." },
  { v: "Wat is move?", a: "Bestanden verplaatsen, of een bestand of map hernoemen.", o: "Navigeren",
    uitleg: "De cursus vraagt om de help te bekijken met move /?. Daar staat wat het commando doet." },
  { v: "Wat is find?", a: "Tekst zoeken in een bestand of in de uitvoer van een commando.", o: "Navigeren",
    uitleg: "De cursus vraagt om de help te bekijken met find /?. Daar staat wat het commando doet." },
  { v: "Wat is findstr?", a: "Uitgebreider tekst zoeken, ook met reguliere expressies.", o: "Navigeren",
    uitleg: "De cursus vraagt om de help te bekijken met findstr /?. Daar staat wat het commando doet." },
  { v: "Wat is copy?", a: "Bestanden kopiëren.", o: "Navigeren",
    uitleg: "De cursus vraagt om de help te bekijken met copy /?. Daar staat wat het commando doet." },
  { v: "Wat is robocopy?", a: "\"Robust copy\": mappen en grote hoeveelheden bestanden kopiëren.", o: "Navigeren",
    uitleg: "De cursus vraagt om de help te bekijken met robocopy /?. Daar staat wat het commando doet." },
  { v: "Bekijk de help van move, find, findstr, copy en robocopy.", a: "C:\\> move /?\nC:\\> find /?\nC:\\> findstr /?\nC:\\> copy /?\nC:\\> robocopy /?", o: "Navigeren", oefening: true,
    uitleg: "/? achter elk commando toont de help van dat commando.\nmove = verplaatsen, find en findstr = tekst zoeken, copy en robocopy = kopiëren." },
  // ===== Netwerkinstellingen =====
  { v: "Welk commando toont snel de netwerkinstellingen van je netwerkadapters?", a: "ipconfig", o: "Netwerkinstellingen" },
  { v: "Geef twee adressen die je met ipconfig kan bekijken.", a: "Het IP-adres en het MAC-adres.", o: "Netwerkinstellingen",
    uitleg: "IP-adres = het adres van je computer in het netwerk, bv. 192.168.1.5. Het kan veranderen, bv. als je het via DHCP krijgt.\nMAC-adres = het vaste, unieke adres van de netwerkkaart zelf: 48 bits, geschreven als 12 hextekens, bv. 00-1A-2B-3C-4D-5E. In ipconfig /all heet het Physical Address.\nDe cursus Windows legt dit niet verder uit: meer in Network Essentials.\n\nMeer over IP- en MAC-adressen in de cursus Network Essentials." },
  { v: "Hoe krijg je uitgebreide informatie over alle netwerkadapters?", a: "C:\\> ipconfig /all", o: "Netwerkinstellingen", oefening: true,
    uitleg: "ipconfig = toon de netwerkinstellingen van je netwerkadapters.\n/all = toon alles: o.a. MAC-adres, IP-adres, subnetmasker, DHCP- en DNS-servers." },
  { v: "Wat doet ipconfig /release?", a: "Het IP-adres vrijgeven dat via DHCP verkregen werd.", o: "Netwerkinstellingen" },
  { v: "Wat doet ipconfig /renew?", a: "Een nieuw IP-adres aanvragen via DHCP.", o: "Netwerkinstellingen" },
  { v: "Waarom test je ipconfig /release en /renew niet op je VM?", a: "Dan verlies je je verbinding.", o: "Netwerkinstellingen" },
  { v: "Wat is DHCP?", a: "Automatische bedeling van IP-adressen door een server of router.", o: "Netwerkinstellingen" },
  { v: "Welke vijf gegevens moest je invullen met ipconfig /all?", a: "MAC-adres (fysiek adres), IP-adres (v4 of v6), netwerkmasker (subnet mask), DHCP-server en DNS-servers.", o: "Netwerkinstellingen" },
  { v: "Hoe heet het MAC-adres in de uitvoer van ipconfig /all?", a: "Physical Address (fysiek adres).", o: "Netwerkinstellingen" },
  { v: "Zoek het MAC-adres, het IP-adres, het netwerkmasker, de DHCP-server en de DNS-server van je netwerkadapter.", a: "C:\\> ipconfig /all", o: "Netwerkinstellingen", oefening: true,
    uitleg: "ipconfig /all = alle informatie over je netwerkadapters.\nIn de uitvoer: MAC-adres = Physical Address, verder IPv4 Address, Subnet Mask, DHCP Server en DNS Servers." },
  // ===== Systeeminformatie =====
  { v: "Welk commando toont processor, besturingssysteem, hotfixes en netwerkadapters?", a: "systeminfo", o: "Systeeminformatie" },
  { v: "Vraag de systeeminfo van je computer op.", a: "C:\\> systeminfo", o: "Systeeminformatie", oefening: true,
    uitleg: "systeminfo = toon informatie over je computer: processor, besturingssysteem, geïnstalleerde hotfixes, netwerkadapters met IP-adressen…" },
  // ===== Redirection en piping =====
  { v: "Wat is input redirection, en met welk teken?", a: "Een bestand als input voor een commando. Teken: <", o: "Redirection en piping",
    uitleg: "Net zoals bij Linux.\n\n>> voegt achteraan een bestand toe, > overschrijft het." },
  { v: "Wat is output redirection, en met welk teken?", a: "De output die normaal op het scherm komt, naar een bestand sturen. Teken: >", o: "Redirection en piping" },
  { v: "Wat doet more < text.txt?", a: "De inhoud van text.txt op het scherm tonen; met de spatietoets loop je er rustig door.", o: "Redirection en piping" },
  { v: "Wat doet dir > resultaat.txt?", a: "De output van dir naar het bestand resultaat.txt sturen.", o: "Redirection en piping" },
  { v: "Wat is piping, en met welk teken?", a: "De output van een commando als input voor een volgend commando gebruiken. Teken: |", o: "Redirection en piping" },
  { v: "Waarom gebruik je dir | more?", a: "Zodat de uitvoer niet over je scherm vliegt, maar je ze stap voor stap bekijkt.", o: "Redirection en piping" },
  { v: "Toon de inhoud van je C-schijf met tree, stap voor stap.", a: "C:\\> tree c:\\ | more", o: "Redirection en piping", oefening: true,
    uitleg: "tree c:\\ = toon alle mappen van C: als een boom.\n| = piping: de output van tree gaat naar more.\nmore = toont de uitvoer stap voor stap (spatietoets)." },
  { v: "Maak in de map test een tekstbestand met als inhoud \"Dit is mijn eerste command prompt bestand\".", a: "C:\\> cd c:\\test\nC:\\test> echo Dit is mijn eerste command prompt bestand > bestand.txt", o: "Redirection en piping", oefening: true,
    uitleg: "cd c:\\test = ga naar de map test (de prompt wordt C:\\test>).\necho toont de tekst die erachter staat.\n> = output redirection: die tekst verschijnt niet op het scherm, maar gaat naar het bestand bestand.txt in de map test." },
  { v: "Vraag de systeeminfo op en bewaar ze meteen in systeminfo.txt.", a: "C:\\> systeminfo > systeminfo.txt", o: "Redirection en piping", oefening: true,
    uitleg: "systeminfo toont heel wat informatie over je computer: processor, besturingssysteem, geïnstalleerde hotfixes, netwerkadapters met IP-adressen…\n> = output redirection: die informatie verschijnt niet op het scherm, maar gaat naar het bestand systeminfo.txt in de map waar je staat." },
  { v: "Een bestand met tekst maken: echo en >", a: "C:\\test> echo Dit is mijn eerste command prompt bestand > bestand.txt\n\necho geeft de tekst die erachter staat.\n> stuurt die tekst niet naar het scherm, maar naar een bestand. Bestaat bestand.txt nog niet, dan wordt het gemaakt in de map waar je staat.\n\nOp dezelfde manier bewaar je de uitvoer van een ander commando in een bestand, bv. systeminfo > systeminfo.txt.", o: "Redirection en piping", extra: true,
    uitleg: "De cursus gebruikt echo in de opdrachten, maar legt het niet uit." },
  { v: ">> : tekst achteraan een bestand toevoegen", a: "C:\\test> echo Nog een regel >> bestand.txt\n\n>> zet de tekst achteraan in een bestaand bestand. Met > wordt een bestaand bestand overschreven.", o: "Redirection en piping", extra: true,
    uitleg: "Niet uit de Windows-cursus." },
  { v: "Toon sorteer.txt gesorteerd op het eerste cijfer.", a: "C:\\> sort < sorteer.txt", o: "Redirection en piping", oefening: true,
    uitleg: "sort = sorteer de regels.\n< sorteer.txt = input redirection: sort leest het bestand sorteer.txt (van Canvas).\n\nInhoud van sorteer.txt (van Canvas):\n3) regel 3 | e) regel 5\n5) regel 5 | a) regel 1\n1) regel 1 | c) regel 3\n2) regel 2 | d) regel 4\n4) regel 4 | b) regel 2\n\nResultaat op het cijfer: 1) … 2) … 3) … 4) … 5) …\nResultaat op de letters: 5) regel 5 | a) · 4) regel 4 | b) · 1) regel 1 | c) · 2) regel 2 | d) · 3) regel 3 | e)" },
  { v: "Toon sorteer.txt gesorteerd op de letters.", a: "C:\\> sort /+14 < sorteer.txt", o: "Redirection en piping", oefening: true,
    uitleg: "sort = sorteer de regels.\n/+14 = sorteer vanaf het 14de teken van elke regel (daar staan de letters).\n< sorteer.txt = sort leest het bestand.\n\n/+n = sorteren vanaf teken n. De letter (a–e) staat in dit bestand op teken 14 (tel spaties en tekens mee: 3 ) spatie r e g e l spatie 3 spatie | spatie e).\nOpgelet: in je Excel stond sort /+2. Dat sorteert vanaf het haakje en geeft hier dezelfde volgorde als op het cijfer, niet op de letters." },
  { v: "Toon de inhoud van text.txt op het scherm met more, via input redirection.", a: "C:\\> more < text.txt", o: "Redirection en piping", oefening: true,
    uitleg: "more = toon tekst stap voor stap (spatietoets).\n< text.txt = input redirection: more leest het bestand text.txt." },
  { v: "Stuur de inhoud van de huidige map naar het bestand resultaat.txt.", a: "C:\\> dir > resultaat.txt", o: "Redirection en piping", oefening: true,
    uitleg: "dir = toon de inhoud van de huidige map.\n> resultaat.txt = output redirection: de uitvoer gaat niet naar het scherm, maar naar het bestand resultaat.txt." },
  { v: "Toon de inhoud van de huidige map stap voor stap.", a: "C:\\> dir | more", o: "Redirection en piping", oefening: true,
    uitleg: "dir = toon de inhoud van de map.\n| = piping: de output van dir gaat naar more.\nmore = toont het stap voor stap, zodat de uitvoer niet over je scherm vliegt." },
  { v: "C:\\Users\\ehbstudent> echo 789456123 > sorteer.txt\nC:\\Users\\ehbstudent> more < sorteer.txt\n\nWat toont more?", a: "789456123", o: "Redirection en piping", oefening: true, extra: true,
    uitleg: "echo 789456123 = schrijf de tekst 789456123.\n> sorteer.txt = die tekst gaat niet naar het scherm, maar naar het bestand sorteer.txt.\nmore < sorteer.txt = more leest het bestand en toont de inhoud op het scherm." },
  { v: "Het bestand sorteer.txt bevat 1 regel: 789456123.\nC:\\Users\\ehbstudent> sort < sorteer.txt\n\nWaarom krijg je 789456123 en niet 123456789?", a: "sort sorteert regels, geen tekens binnen een regel. Er is maar 1 regel, dus er valt niets te sorteren.", o: "Redirection en piping", oefening: true, extra: true,
    uitleg: "sort zet de regels van een bestand in volgorde. De tekens binnen een regel blijven staan zoals ze staan. Wil je cijfers sorteren, dan moet elk cijfer op een eigen regel staan." },
  { v: "Maak sorteer.txt opnieuw, met 9, 8, 5 en 6 elk op een eigen regel.", a: "C:\\Users\\ehbstudent> echo 9 > sorteer.txt\nC:\\Users\\ehbstudent> echo 8 >> sorteer.txt\nC:\\Users\\ehbstudent> echo 5 >> sorteer.txt\nC:\\Users\\ehbstudent> echo 6 >> sorteer.txt", o: "Redirection en piping", oefening: true, extra: true,
    uitleg: "Elke echo schrijft 1 regel.\n> bij de eerste = maak het bestand opnieuw aan (de oude inhoud verdwijnt).\n>> bij de andere = zet de regel achteraan in het bestand." },
  { v: "Je maakt sorteer.txt met:\nC:\\Users\\ehbstudent> echo 9 > sorteer.txt\nC:\\Users\\ehbstudent> echo 8 >> sorteer.txt\n\nWaarom > bij de eerste echo en >> bij de tweede?", a: "> maakt het bestand opnieuw aan: de oude regel 789456123 verdwijnt. >> zet de tekst achteraan erbij.", o: "Redirection en piping", oefening: true, extra: true,
    uitleg: "Schrijf je overal >, dan wordt het bestand elke keer opnieuw aangemaakt en hou je enkel de laatste regel over.\nSchrijf je ook bij de eerste >>, dan blijft de oude inhoud (789456123) bovenaan staan." },
  { v: "sorteer.txt bevat 4 regels: 9, 8, 5 en 6.\nC:\\Users\\ehbstudent> sort < sorteer.txt\n\nWat toont sort?", a: "5\n6\n8\n9", o: "Redirection en piping", oefening: true, extra: true,
    uitleg: "sort < sorteer.txt = sort leest het bestand (input redirection) en zet de regels in volgorde, van klein naar groot. Het bestand zelf verandert niet: sort toont het resultaat enkel op het scherm." },
  // ===== Meerdere commando's =====
  { v: "Wat doet commando1 & commando2?", a: "Eerst het eerste commando, dan het tweede.", o: "Meerdere commando's" },
  { v: "Wat doet commando1 && commando2?", a: "Eerst het eerste, dan het tweede, maar enkel als het eerste succesvol was (error code 0).", o: "Meerdere commando's" },
  { v: "Wat doet commando1 || commando2?", a: "Eerst het eerste, dan het tweede, maar enkel als het eerste niet succesvol was (error code > 0).", o: "Meerdere commando's" },
  { v: "Waarvoor dienen de haakjes in (commando1 & commando2)?", a: "Om commando's te groeperen.", o: "Meerdere commando's" },
  { v: "Welke error code betekent dat een commando succesvol was? En niet succesvol?", a: "0 = succesvol. Groter dan 0 = niet succesvol.", o: "Meerdere commando's" },
  { v: "Toon beide sorteringen van sorteer.txt onder elkaar, in 1 commando.", a: "C:\\> sort < sorteer.txt & sort /+14 < sorteer.txt", o: "Meerdere commando's", oefening: true,
    uitleg: "sort < sorteer.txt = sorteer op het eerste cijfer.\n& = voer daarna het volgende commando uit.\nsort /+14 < sorteer.txt = sorteer op de letters." },
  { v: "Schrijf beide sorteringen weg naar gesorteerd.txt.", a: "C:\\> (sort < sorteer.txt & sort /+14 < sorteer.txt) > gesorteerd.txt", o: "Meerdere commando's", oefening: true,
    uitleg: "De haakjes ( ) groeperen beide sort-commando's.\n& = voer ze na elkaar uit.\n> gesorteerd.txt = de output van allebei gaat naar het bestand gesorteerd.txt.\n\nBv. om de output van beide samen naar één bestand te sturen." },
  { v: "Schrijf enkel de regels met IPv4 uit ipconfig naar ip.txt en toon daarna \"Gelukt!\" als de tekst gevonden was.", a: "C:\\> ipconfig | find \"IPv4\" > ip.txt && echo Gelukt!", o: "Meerdere commando's", oefening: true,
    uitleg: "ipconfig = toon je netwerkinstellingen.\n| find \"IPv4\" = hou enkel de regels met IPv4 over.\n> ip.txt = schrijf die regels naar ip.txt.\n&& echo Gelukt! = toon Gelukt! enkel als find de tekst gevonden heeft (error code 0)." },
  { v: "Roep TryMulti tweemaal na elkaar aan met de juiste parameter.", a: "C:\\> TryMulti Ruben && TryMulti Ruben", o: "Meerdere commando's", oefening: true,
    uitleg: "TryMulti Ruben = start het programma met de parameter Ruben (tip uit de cursus: de oudste zoon van Jakob uit de bijbel).\n&& = de tweede keer gebeurt enkel als de eerste succesvol was." },
  { v: "C:\\Users\\ehbstudent> echo Eerste & echo Tweede\n\nWat toont dit?", a: "Eerste\nTweede", o: "Meerdere commando's", oefening: true, extra: true,
    uitleg: "& = voer eerst het eerste commando uit, en daarna het tweede, wat er ook gebeurt.\nElke echo toont zijn tekst op een eigen regel." },
  { v: "C:\\Users\\ehbstudent> dir bestaatniet.txt && echo Gevonden\n\nWat toont dit, als het bestand bestaatniet.txt niet bestaat?", a: "Enkel de foutmelding van dir (Bestand niet gevonden). \"Gevonden\" verschijnt niet.", o: "Meerdere commando's", oefening: true, extra: true,
    uitleg: "dir zoekt het bestand en vindt het niet: het commando mislukt (error code > 0).\n&& = voer het tweede commando enkel uit als het eerste succesvol was (error code 0). Dus echo Gevonden wordt overgeslagen." },
  { v: "Toon \"Niet gevonden\" enkel als find de tekst IPv4 niet vindt in de uitvoer van ipconfig.", a: "C:\\> ipconfig | find \"IPv4\" || echo Niet gevonden", o: "Meerdere commando's", oefening: true, extra: true,
    uitleg: "ipconfig = toon je netwerkinstellingen.\n| find \"IPv4\" = hou enkel de regels met IPv4 over.\n|| = voer het tweede commando enkel uit als het eerste mislukt (error code > 0). find mislukt als het de tekst niet vindt.\necho Niet gevonden = toon de tekst Niet gevonden." },
  // ===== Wachtwoord wijzigen =====
  { v: "Wat vul je in op het scherm Change a password?", a: "Je oude wachtwoord, daarna twee keer het nieuwe.", o: "Wachtwoord wijzigen", imgAntwoord: "afbeeldingen/DesktopOS_windows_wc1/wachtwoord_wijzigen.jpg",
    uitleg: "Het nieuwe wachtwoord typ je twee keer, zodat een tikfout opvalt. Verder is er geen extra controle: een vergissing is snel gebeurd." },
  { v: "Hoe wijzig je je wachtwoord in Windows? En via RDP?", a: "Ctrl+Alt+Delete en Change a password. Via RDP: Ctrl+Alt+End.", o: "Wachtwoord wijzigen",
    uitleg: "Usermanagement komt aan bod in het volgende werkcollege." },
  { v: "Waarom moet je opletten als je je wachtwoord wijzigt?", a: "Er is geen extra controle: een wijziging en een vergissing zijn even snel gebeurd.", o: "Wachtwoord wijzigen" },
  { v: "Waarmee beheert de school de gebruikers en wachtwoorden?", a: "Active Directory.", o: "Wachtwoord wijzigen",
    uitleg: "Over Active Directory volgt later meer." },
  { v: "Wat is single sign-on? Geef voorbeelden.", a: "Met dezelfde login inloggen op meerdere platformen en applicaties, bv. Office, Canvas, wifi.", o: "Wachtwoord wijzigen" },
  // ===== VPN =====
  { v: "Verbind je VM via VPN met het schoolnetwerk en open daarna de fileserver van de school.", a: "1. Installeer de VPN volgens de procedure op de intranetcursus of via VPN Toegang (studenten campus Kaai) op Confluence.\n2. Maak verbinding met het schoolnetwerk.\n3. Open in de Verkenner \\\\dt-srv-file1.ehb.local\\ om bestanden af te halen of in te dienen.", o: "VPN", oefening: true,
    uitleg: "Figuur: www.tp-link.com" },
  { v: "Waarvoor staat VPN, en wat is het?", a: "Virtual Private Network: een beveiligde verbinding tussen jouw apparaat en een ander netwerk over het internet.", o: "VPN" },
  { v: "Wat doet een VPN met je internetverkeer?", a: "Het versleutelt het, zodat anderen niet kunnen zien wat je online doet.", o: "VPN" },
  { v: "Geef de 4 toepassingen van een VPN uit de cursus.", a: "Privacy en anonimiteit (IP verbergen) · veilig op openbare wifi · toegang tot geblokkeerde of regiogebonden content · veilig werken op afstand.", o: "VPN" },
  { v: "Wat gebeurt er in de 2 stappen bij het opzetten van een VPN?", a: "1. Je computer maakt op basis van gebruikersnaam en wachtwoord een beveiligde verbinding met het netwerk. 2. Al het verkeer wordt vanaf dan versleuteld.", o: "VPN" },
  { v: "Hoe lijkt het na het opzetten van de VPN-tunnel?", a: "Alsof je op het interne netwerk zit.", o: "VPN" },
  { v: "Wat staat er op de plaats van de nummers?", a: "1 Internet · 2 Client · 3 VPN Server (Gateway) · 4 VPN Tunnel", o: "VPN", img: "afbeeldingen/DesktopOS_windows_wc1/vpn_vraag.jpg", imgAntwoord: "afbeeldingen/DesktopOS_windows_wc1/vpn.jpg" },
  { v: "Wat doen sommige VPN-implementaties met al je netwerkverkeer?", a: "Ze sturen ALLE netwerkpoorten door de VPN-tunnel, dus ook je surfgedrag gaat via dat netwerk.", o: "VPN" },
  // ===== Netwerklocaties =====
  { v: "Welke map werd voor dit werkcollege op de fileserver aangemaakt, en waarvoor dient ze?", a: "WeWinShare: een map waar je bestanden aan kan toevoegen.", o: "Netwerklocaties",
    uitleg: "Je koppelt ze als netwerkschijf met een eigen schijfletter: visueel met Map network drive, of in CMD met net use." },
  { v: "Wanneer kan je de fileserver van de school bereiken?", a: "Als je verbonden bent met het netwerk van de school: fysiek of via VPN.", o: "Netwerklocaties" },
  { v: "Hoe voeg je in Windows een netwerklocatie toe zodat ze een eigen schijfletter krijgt?", a: "Als netwerkschijf (Map network drive).", o: "Netwerklocaties",
    uitleg: "Een netwerkschijf is een map op een andere computer, bv. de fileserver van de school, die je in Windows ziet met een eigen schijfletter (bv. Z:). Zo open je die map in de Verkenner net als een schijf op je eigen pc.\nZo doe je het: Verkenner (Win+E) → This PC → See more (…) → Map network drive → kies een schijfletter en geef het pad in, bv. \\\\dt-srv-file1.ehb.local\\Studentenstorage\\TI\\Desktop OS\\WeWinShare → log in met je EhB-gegevens.\nIn CMD kan het ook, met net use." },
  { v: "Open de Verkenner met het toetsenbord.", a: "  Win+E", o: "Netwerklocaties", oefening: true },
  { v: "Hoe voeg je visueel een netwerkschijf toe?", a: "Verkenner (Win+E) → This PC → See more (…) → Map network drive → schijfletter + pad.", o: "Netwerklocaties", img: "afbeeldingen/DesktopOS_windows_wc1/map_network_drive_menu.jpg", imgAntwoord: "afbeeldingen/DesktopOS_windows_wc1/map_network_drive.jpg" },
  { v: "Met welk commando voeg je in CMD een netwerkschijf toe? Hoe bekijk je de help?", a: "C:\\> net use\nC:\\> net use /?", o: "Netwerklocaties", oefening: true,
    uitleg: "net use = beheer netwerkschijven; zonder iets erachter toont het je huidige netwerkschijven.\n/? = toon de help." },
  { v: "Voeg netwerkschijf Z: toe naar WeWinShare, zonder dat je telkens je wachtwoord moet ingeven.", a: "C:\\> net use Z: \"\\\\dt-srv-file1.ehb.local\\Studentenstorage\\TI\\Desktop OS\\WeWinShare\" /savecred", o: "Netwerklocaties", oefening: true,
    uitleg: "net use Z: = koppel een netwerkschijf aan de letter Z:.\n\"\\\\dt-srv-file1…\\WeWinShare\" = het pad naar de map op de fileserver, tussen quotes omdat er een spatie in zit (Desktop OS).\n/savecred = je credentials worden bewaard. Met /persistent:yes erbij blijft de schijf ook na opnieuw inloggen.\n\nMet Reconnect at sign-in blijft de schijf ook na opnieuw inloggen." },
  { v: "Waarom staan er quotes rond het pad bij net use?", a: "Er zit een spatie in het pad (Desktop OS).", o: "Netwerklocaties" },
  { v: "Maak met echo een bestand met je naam op netwerkschijf Z:.", a: "C:\\> echo Hallo > Z:\\voornaam.familienaam.txt", o: "Netwerklocaties", oefening: true,
    uitleg: "echo Hallo = geef de tekst Hallo.\n> Z:\\voornaam.familienaam.txt = output redirection: die tekst gaat naar een nieuw bestand op netwerkschijf Z:." },
  { v: "Hoe verwijder je netwerkschijf Z:, en waarom doe je dat?", a: "C:\\> net use Z: /delete", o: "Netwerklocaties", oefening: true,
    uitleg: "net use Z: = de netwerkschijf Z:.\n/delete = verwijder die koppeling. Zo kunnen studenten die met jouw VM verbinden niet aan je netwerkschijf." },
  // ===== Winget =====
  { v: "Wat is het voordeel van winget?", a: "Met één commando beheer je programma's, zonder installers te downloaden.", o: "Winget",
    uitleg: "Installer = het installatieprogramma (bv. setup.exe) dat je anders eerst van een website haalt.\n\nVergelijk met apt bij Linux.\n\nJe moet de basiscommando's kennen en kunnen gebruiken. Heb je geen Windows-toestel, of was het al in orde tijdens de bootcampweek, dan mag je de installatie overslaan. Vergelijk met apt bij Linux." },
  { v: "Wat is winget?", a: "Windows Package Manager: software installeren, updaten en verwijderen via de command line.", o: "Winget" },
  { v: "Hoe toon je alle winget-commando's en opties?", a: "C:\\> winget --help", o: "Winget", oefening: true,
    uitleg: "winget = de Windows Package Manager.\n--help = toon alle commando's en opties." },
  { v: "Hoe zoek je een pakket in de winget-database?", a: "C:\\> winget search pakket", o: "Winget", oefening: true,
    uitleg: "winget search = zoek software in de winget-database.\npakket = de naam van wat je zoekt, bv. VLC." },
  { v: "Hoe toon je alle geïnstalleerde software met winget?", a: "C:\\> winget list", o: "Winget", oefening: true,
    uitleg: "winget list = een lijst van alle geïnstalleerde software." },
  { v: "Hoe installeer je een pakket met winget?", a: "C:\\> winget install pakket", o: "Winget", oefening: true,
    uitleg: "winget install = installeer software.\npakket = de naam of het ID van het pakket." },
  { v: "Hoe werk je één pakket bij? En alles in één keer?", a: "C:\\> winget upgrade pakket\nC:\\> winget upgrade --all", o: "Winget", oefening: true,
    uitleg: "winget upgrade pakket = werk één pakket bij.\n--all = werk alle beschikbare updates in één keer bij." },
  { v: "Hoe verwijder je een pakket met winget?", a: "C:\\> winget uninstall pakket", o: "Winget", oefening: true,
    uitleg: "winget uninstall = verwijder software.\npakket = de naam of het ID van het pakket." },
  { v: "Zoek en installeer VLC media player met winget.", a: "C:\\> winget search VLC\nC:\\> winget install VideoLAN.VLC", o: "Winget", oefening: true,
    uitleg: "winget search VLC = zoek VLC; in de resultaten zie je het ID VideoLAN.VLC.\nwinget install VideoLAN.VLC = installeer het pakket met dat ID." },
  { v: "Zoek en installeer 7-Zip met winget.", a: "C:\\> winget search 7-Zip\nC:\\> winget install 7zip.7zip", o: "Winget", oefening: true,
    uitleg: "winget search 7-Zip = zoek 7-Zip; in de resultaten zie je het ID 7zip.7zip.\nwinget install 7zip.7zip = installeer het pakket met dat ID." },
  { v: "Verwijder VLC weer en bekijk de geïnstalleerde pakketten.", a: "C:\\> winget uninstall VideoLAN.VLC\nC:\\> winget list", o: "Winget", oefening: true,
    uitleg: "winget uninstall VideoLAN.VLC = verwijder VLC.\nwinget list = toon de geïnstalleerde software: VLC staat er niet meer bij." },
  // ===== Extra handige tools =====
  { v: "Office 365", a: "Als student aan de Erasmushogeschool heb je een Office 365-account: je gebruikt de apps online of downloadt ze, via office.com.", o: "Extra handige tools", extra: true, nietTeKennen: true },
  { v: "PowerToys", a: "Een verzameling hulpprogramma's om je Windows verder op maat aan te passen en de gebruikservaring te verbeteren. Op de officiële GitHub-repository (github.com/microsoft/PowerToys) worden developers opgeroepen om tools bij te dragen; daar vind je ook de laatste versie (.msi).", o: "Extra handige tools", extra: true, nietTeKennen: true },
  { v: "Fancy Zones", a: "Een window manager om zones te maken waarin je programma's getoond worden (handig op grote schermen).", o: "Extra handige tools", extra: true, nietTeKennen: true },
  { v: "Shortcut Guide", a: "Houd de Windows-toets langer dan een seconde in en je ziet de sneltoetsen met de Windows-toets.", o: "Extra handige tools", extra: true, nietTeKennen: true },
  { v: "PowerRename", a: "Bestanden in de Verkenner selecteren en automatisch hernoemen, ook met reguliere expressies.", o: "Extra handige tools", extra: true, nietTeKennen: true },
  { v: "WinDirStat", a: "Visualiseert de bestanden op je schijf, gegroepeerd per map, zodat je ziet wat de meeste ruimte inneemt.", o: "Extra handige tools", extra: true, nietTeKennen: true, img: "afbeeldingen/DesktopOS_windows_wc1/windirstat.jpg" },
  { v: "AutoHotKey", a: "Koppelt toetsen aan scripts die toetsaanslagen, muisbewegingen en muisklikken simuleren, bv. met één toets de startlijnen van C++ typen.", o: "Extra handige tools", extra: true, nietTeKennen: true },
  { v: "Discord", a: "Een handige communicatietool.", o: "Extra handige tools", extra: true, nietTeKennen: true },
  { v: "Wat is PowerToys? Noem de drie tools uit de cursus.", a: "Hulpprogramma's van Microsoft om Windows op maat aan te passen: Fancy Zones, Shortcut Guide en PowerRename.", o: "Extra handige tools", extra: true, nietTeKennen: true },
  { v: "Wat doet Fancy Zones?", a: "Zones maken waarin je programma's getoond worden; handig om je scherm in te delen.", o: "Extra handige tools", extra: true, nietTeKennen: true },
  { v: "Wat doet Shortcut Guide?", a: "Als je de Windows-toets langer dan een seconde inhoudt, toont het de sneltoetsen met de Windows-toets.", o: "Extra handige tools", extra: true, nietTeKennen: true },
  { v: "Wat doet PowerRename?", a: "Bestanden in de Verkenner automatisch hernoemen, ook met reguliere expressies.", o: "Extra handige tools", extra: true, nietTeKennen: true },
  { v: "Wat doet WinDirStat?", a: "Visueel tonen welke mappen en bestanden de meeste schijfruimte innemen.", o: "Extra handige tools", extra: true, nietTeKennen: true, img: "afbeeldingen/DesktopOS_windows_wc1/windirstat.jpg" },
  { v: "Wat doet AutoHotKey?", a: "Toetsen koppelen aan scripts die toetsaanslagen, muisbewegingen en muisklikken simuleren.", o: "Extra handige tools", extra: true, nietTeKennen: true },
  { v: "Waarom roept de GitHub-repository van PowerToys developers op?", a: "Om bij te dragen aan het maken van verdere tools.", o: "Extra handige tools", extra: true, nietTeKennen: true },
  { v: "Wat is Discord volgens de cursus?", a: "Een handige communicatietool.", o: "Extra handige tools", extra: true, nietTeKennen: true },
  { v: "Waar vind je de Office-apps als EhB-student?", a: "Via office.com, met je Office 365-account.", o: "Extra handige tools", extra: true, nietTeKennen: true },
];

